create table if not exists public.location_favorites (id uuid primary key default gen_random_uuid(), location_id uuid not null references public.locations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), unique(location_id,user_id));
create table if not exists public.location_route_events (id uuid primary key default gen_random_uuid(), location_id uuid not null references public.locations(id) on delete cascade, user_id uuid references auth.users(id) on delete set null, source text not null default 'map', from_lat numeric, from_lng numeric, created_at timestamptz not null default now());
create index if not exists idx_location_favorites_user on public.location_favorites(user_id,created_at desc);
create index if not exists idx_location_favorites_location on public.location_favorites(location_id);
create index if not exists idx_location_route_events_location on public.location_route_events(location_id,created_at desc);
create or replace function public.location_favorite_counts(p_location_ids uuid[]) returns table(location_id uuid,favorite_count bigint,route_count bigint) language sql stable security invoker as $$ select l.id,coalesce((select count(*) from public.location_favorites f where f.location_id=l.id),0),coalesce((select count(*) from public.location_route_events r where r.location_id=l.id),0) from unnest(p_location_ids) ids(id) join public.locations l on l.id=ids.id; $$;
create or replace function public.my_favorite_locations() returns setof public.locations language sql stable security invoker as $$ select l.* from public.locations l join public.location_favorites f on f.location_id=l.id where f.user_id=auth.uid() order by f.created_at desc; $$;
